import boto3
import json

def send_to_dead_letter_queue(dead_letter_queue_url: str, message_body: dict, message_attributes: dict = None):
    sqs_client = boto3.client('sqs')  # AWS SDK import
    if message_attributes is None:
        message_attributes = {}

    # Convert message_attributes to the format expected by SQS
    sqs_message_attributes = {
        k: {'DataType': 'String', 'StringValue': str(v)} for k, v in message_attributes.items()
    }

    response = sqs_client.send_message(
        QueueUrl=dead_letter_queue_url,
        MessageBody=json.dumps(message_body),
        MessageAttributes=sqs_message_attributes
    )
    return response

import boto3
import json

def batch_publish_events(topic_arn: str, messages: list[dict]):
    sns_client = boto3.client('sns')  # AWS SDK import
    entries = []
    for i, message in enumerate(messages):
        entries.append({
            'Id': str(i),
            'Message': json.dumps(message),
            'MessageStructure': 'json'
        })
    response = sns_client.publish_batch(
        TopicArn=topic_arn,
        PublishBatchRequestEntries=entries
    )
    return response

import boto3

def summarize_message_processing(metric_namespace: str, metric_name: str, value: float, dimensions: list[dict] = None):
    cloudwatch_client = boto3.client('cloudwatch')  # AWS SDK import
    metric_data = [
        {
            'MetricName': metric_name,
            'Value': value,
            'Unit': 'Count',
        },
    ]
    if dimensions:
        metric_data[0]['Dimensions'] = dimensions

    response = cloudwatch_client.put_metric_data(
        Namespace=metric_namespace,
        MetricData=metric_data
    )
    return response

import boto3
import json
import datetime

def store_message_audit_record(table_name: str, message_id: str, payload: dict, status: str, processing_timestamp: str = None):
    dynamodb_client = boto3.client('dynamodb')  # AWS SDK import

    if processing_timestamp is None:
        processing_timestamp = datetime.datetime.now(datetime.timezone.utc).isoformat()

    item = {
        'messageId': {'S': message_id},
        'payload': {'S': json.dumps(payload)},
        'status': {'S': status},
        'processingTimestamp': {'S': processing_timestamp}
    }

    response = dynamodb_client.put_item(
        TableName=table_name,
        Item=item
    )
    return response
